INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (6258, 'Gaofen-11-04', NULL, NULL, 'Earth Science', 'SSO', 'Sun-Synchronous Orbit', 'Gaofen is a series of civilian Earth observation satellites developed and launched for the China High-definition Earth Observation System (CHEOS), a state-sponsored programme aimed to develop a near-real time, all-weather, global surveillance network consisting of satellite, near-space (stratosphere) airships, and aerial observation platforms.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (5788, 'Parus 98', NULL, NULL, 'Navigation', 'LEO', 'Low Earth Orbit', 'Navigation satellite providing location information for the Tsiklon-B navigation system');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (1431, 'Sputnik 2', NULL, NULL, 'Test Flight', 'LEO', 'Low Earth Orbit', 'Second artificial satellite and first to carry an animal into orbit.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (1436, 'D-1 1', NULL, NULL, 'Earth Science', 'LEO', 'Low Earth Orbit', 'First complex scientific satellite with 12 experiments and a total mass of1327 kg. It failed to reach orbit due to a launch vehicle failure.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (5881, 'CERES', NULL, NULL, 'Government/Top Secret', 'LEO', 'Low Earth Orbit', 'CERES (CapacitÉ de Renseignement Électromagnétique Spatiale) is a space-based signal intelligence (SIGNIT) system consisting of three satellites constellation.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (680, 'Michibiki 4 (QZS-4)', NULL, NULL, 'Navigation', 'GSTO', 'Geosynchronous Transfer Orbit', 'The Quasi-Zenith Satellite System (QZSS) is a three-satellite regional time transfer system and the satellite-based augmentation system for the GPS that would be receivable within Japan. The primary purpose of QZSS is to increase the availability of GPS in Japan''s numerous urban canyons, where only satellites at very high elevation can be seen. A secondary function is performance enhancement, increasing the accuracy and reliability of GPS derived navigation solutions. A single satellite weighs about 4000 kg, has an expected lifetime of 15 years and is put in a elliptical, highly inclined geosynchronous orbit.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (822, 'GCOM-C1 & SLATS', NULL, NULL, 'Earth Science', 'SSO', 'Sun-Synchronous Orbit', 'GCOM-C1 is another satellite in JAXA''s Earth observation Global Change Observation Mission (GCOM) constellation. This spacecraft is the first satellite in GCOM-C series and is intended to operate in sun-synchronous orbit for 5 years. It aims to collect surface and atmospheric measurements in order to monitor global climate change. Along with it is launched an engineering test satellite SLATS (Super Low Altitude Test Satellite), which is an attempt to develop techniques to operate a satellite in extremely low orbits. SLATS will try achieve that by maintaining position in orbit via ion engines. It will also collect data on atmosphere density and measure atomic oxygen in such low altitudes.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (5840, 'QZS-1R', NULL, NULL, 'Navigation', 'GSTO', 'Geosynchronous Transfer Orbit', 'The Quasi-Zenith Satellite System (QZSS) is a three-satellite regional time transfer system and the satellite-based augmentation system for the GPS that would be receivable within Japan. The primary purpose of QZSS is to increase the availability of GPS in Japan''s numerous urban canyons, where only satellites at very high elevation can be seen. A secondary function is performance enhancement, increasing the accuracy and reliability of GPS derived navigation solutions.
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (492, 'IGS Optical 6', NULL, NULL, 'Government/Top Secret', 'SSO', 'Sun-Synchronous Orbit', 'Information Gathering Satellite (IGS) is a Japanese governmental spy satellite program. IGS Optical 6, as the name suggests, is an optical reconnaissance satellite.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (5893, 'Inmarsat-6 F1', NULL, NULL, 'Communications', 'GTO', 'Geostationary Transfer Orbit', 'Inmarsat-6 is the sixth generation of satellites for the London-based global mobile satellite communications operator Inmarsat. It consists of a dual mission to augment both L-band and Ka-band Global Xpress services.
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (614, 'Michibiki 2 (QZS-2)', NULL, NULL, 'Navigation', 'GSTO', 'Geosynchronous Transfer Orbit', 'The Quasi-Zenith Satellite System (QZSS) is a three-satellite regional time transfer system and the satellite-based augmentation system for the GPS that would be receivable within Japan. The primary purpose of QZSS is to increase the availability of GPS in Japan''s numerous urban canyons, where only satellites at very high elevation can be seen. A secondary function is performance enhancement, increasing the accuracy and reliability of GPS derived navigation solutions. A single satellite weighs about 4000 kg, has an expected lifetime of 15 years and is put in a elliptical, highly inclined geosynchronous orbit.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (395, 'IGS Radar 5', NULL, NULL, 'Government/Top Secret', 'SSO', 'Sun-Synchronous Orbit', 'IGS Radar is a family of Japanese radar reconnaissance satellites that serve both Japan''s national defense and civil natural disaster monitoring. IGS Radar 5 is the fifth generation of satellites. Equipped with synthetic aperture radar, it is able to image targets even in darkness and bad weather.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (1077, 'IGS Optical 7', NULL, NULL, 'Government/Top Secret', 'SSO', 'Sun-Synchronous Orbit', 'Information Gathering Satellite (IGS) is a Japanese governmental spy satellite program. IGS Optical 7, as the name suggests, is an optical reconnaissance satellite.
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (387, 'DSN 2 (Kirameki 2)', NULL, NULL, 'Communications', 'GTO', 'Geostationary Transfer Orbit', 'DSN 2, also known as Kirameki 2, is a geostationary communications satellite to be used for military communications by the Japanese military.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (558, 'Himawari-9', NULL, NULL, 'Earth Science', 'GTO', 'Geostationary Transfer Orbit', 'Himawari-9 is a geostationary weather satellite operated by the Japan Meteorological Agency. It will be placed at 140 degrees East and will replace Himawari-8 in 2022. The satellite is about 3,500 kilograms and has a design life of around 15 years with operational life lasting 8 years.The main instrument aboard is a 16 channel multispectral imager to capture visible light and infrared images of the Asian-Pacific region.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (379, 'TRICOM-1', NULL, NULL, 'Earth Science', 'LEO', 'Low Earth Orbit', 'TRICOM-1 is an experimental 3U cubsat build by University of Tokyo. It is equipped with 5 small cameras for Earth imaging purposes, and is also tasked with storing and transmitting data between ground terminals.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (479, 'TRICOM-1R', NULL, NULL, 'Earth Science', 'LEO', 'Low Earth Orbit', 'TRICOM-1 is an experimental 3U cubsat build by University of Tokyo. It is equipped with 5 small cameras for Earth imaging purposes, and is also tasked with storing and transmitting data between ground terminals.
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (6259, 'Shiyan 10-02', NULL, NULL, 'Government/Top Secret', 'HEO', 'High Earth Orbit', 'Satellite officially declared for spatial environment monitoring and in-orbit technical validation purposes. First satellite is observed to have entered a Molniya orbit.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (981, 'EOS-6 (Oceansat-3) & rideshare', NULL, NULL, 'Earth Science', 'SSO', 'Sun-Synchronous Orbit', 'Oceansat-3 is a part of ISRO''s Oceansat program. Its main purpose is ocean observation, which includes gathering ocean color data, sea surface temperature measurements and wind vector data.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (687, 'EOS-7 & rideshare (SSLV Demo 2)', NULL, NULL, 'Test Flight', 'LEO', 'Low Earth Orbit', 'Second test flight of Indian SSLV (Small Satellite Launch Vehicle). The payloads include an Earth observation satellite EOS-7, Janus-1 from US firm Antaris, and another domestic satellite AzaadiSAT-2.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (6248, 'Yaogan 36 Group 04', NULL, NULL, 'Government/Top Secret', 'LEO', 'Low Earth Orbit', '3 Chinese military reconnaissance satellites.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (6227, 'Metop-SG A3', NULL, NULL, 'Earth Science', 'SSO', 'Sun-Synchronous Orbit', 'Fifth of EUMETSAT''s second generation of Metop weather satellites.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (1245, 'Star One D2 & Eutelsat Quantum', NULL, NULL, 'Communications', 'GTO', 'Geostationary Transfer Orbit', 'Star One D2 is a 6.2 tons satellite built by Space Systems Loral for operator Star One, subsidiary of Brazilian Embratel. Its architecture is based on a SSL-1300 platform and equipped with C, X, Ku and Ka-band transceivers. It will provide communications services to Latin America for at least 15 years.
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (904, 'Al Yah 3 & SES-14', NULL, NULL, 'Communications', 'Super-GTO', 'Supersynchronous Transfer Orbit', 'Al Yah 3 is a geostationary communications satellite built by Orbital ATK for Yahsat. It weighs 3790 kg, carries 53 Ka-band user beams and 4 gateway beams, and is intended for 15 years of operation in orbit. Al Yah 3 will provide telecommunication services to Africa and Brazil. SES-14 is also a communications satellite to be placed in geostationary orbit, replacing NSS-806 satellite. SES-14 coverage includes the Americas and the North Atlantic Region. Spacecraft also carries a hosted payload for NASA, Global-Scale Observations of the Limb and Disk (GOLD) mission, which will be imaging Earth''s thermosphere and ionospehere for two years.');
INSERT INTO core.mission (ll2_id, name, name_ja, name_ja_source, type, orbit, orbit_name, description) VALUES (1374, 'SES-17 & Syracuse 4A', NULL, NULL, 'Communications', 'GTO', 'Geostationary Transfer Orbit', 'SES-17 is a Ka-band high-throughput geostationary communications satellite built by Thales Alenia Space designed to provide mobile internet services to airline passengers over the Americas and the Atlantic Ocean. Syracuse 4A is a French military communications satellite built by Thales Alenia Space.');
